  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Creates a new IPO application for the customer if eligible and no duplicate approved application exists for the same company.
   * Algorithm:
   *   1. Check if the customer is eligible to apply (isEligibleForIPO() returns true). If not, return false.
   *   2. Check if the customer already has an application for the same company with status APPROVAL. If yes, return false.
   *   3. Validate inputs: shares > 0, amount > 0, doc is not null. If any fails, return false.
   *   4. Create a new Application object with the provided parameters (company, shares, amount, doc), status set to PENDING, and customer set to this customer.
   *   5. Add the new application to the customer's applications list.
   *   6. Return true.
   * Related Features: canApplyForIPO, applications, isEligibleForIPO
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input: 
   *   - company : Company - the target company for the IPO application.
   *   - shares : int - the number of shares requested, must be > 0.
   *   - amount : double - the payment amount, must be > 0.
   *   - doc : Document - the legal allowance document, must not be null.
   * Output: boolean - true if the application is created successfully, false otherwise.
   * Pre-condition: The customer must be eligible for IPO. There must be no existing approved application for the same company. Inputs must be valid.
   * Post-condition: If successful, a new PENDING Application is created and added to the customer's applications list.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    // 1. Check if the customer is eligible to apply
    if (!isEligibleForIPO()) {
      return false;
    }
    
    // 2. Check if the customer already has an approved application for the same company
    for (Application existingApp : getApplications()) {
      if (existingApp.getCompany().getName().equals(company.getName()) && 
          existingApp.getStatus() == ApplicationStatus.APPROVAL) {
        return false;
      }
    }
    
    // 3. Validate inputs
    if (shares <= 0 || amount <= 0 || doc == null) {
      return false;
    }
    
    // 4. Create a new Application
    Application newApplication = IpoFactory.eINSTANCE.createApplication();
    newApplication.setCompany(company);
    newApplication.setNumberOfShares(shares);
    newApplication.setAmountOfMoney(amount);
    newApplication.setDocument(doc);
    newApplication.setStatus(ApplicationStatus.PENDING);
    newApplication.setCustomer(this);
    
    // 5. Add the new application to the customer's applications list
    getApplications().add(newApplication);
    
    // 6. Return true
    return true;
  }

